results = []
print("="*65)
print("STOCK SCAN - Jan 13, 2026 (3hr delayed)")
print("="*65)

for ticker, data in stock_data.items():
    closes = data["closes"]
    price = data["price"]

    sma20 = sum(closes[-20:]) / 20
    sma50 = sum(closes[-50:]) / 50

    gains, losses = [], []
    for i in range(1, len(closes)):
        change = closes[i] - closes[i-1]
        gains.append(max(change, 0))
        losses.append(max(-change, 0))
    avg_gain = sum(gains[-14:]) / 14
    avg_loss = sum(losses[-14:]) / 14
    rs = avg_gain / avg_loss if avg_loss > 0 else 100
    rsi = 100 - (100 / (1 + rs))

    regime = "BULL" if price > sma50 else "BEAR"
    mom_5d = (price - closes[-6]) / closes[-6] * 100

    score = 0
    if 30 <= rsi <= 45: score += 3
    elif 45 < rsi <= 55: score += 2
    elif rsi < 30: score += 1
    if regime == "BULL": score += 2
    if price > sma20 > sma50: score += 2
    if -5 < mom_5d < 0: score += 1

    results.append({"ticker": ticker, "price": price, "rsi": round(rsi,1), "regime": regime, "sma50": round(sma50,2), "mom": round(mom_5d,1), "score": score})

results.sort(key=lambda x: x["score"], reverse=True)

print("\nRANKED BY SCORE:")
print("-"*65)
for r in results:
    flag = "***" if r["score"] >= 5 else ""
    print(f"{r['ticker']:6} ${r['price']:>7.2f} | RSI:{r['rsi']:>5.1f} | {r['regime']:4} | Mom:{r['mom']:>+5.1f}% | Score:{r['score']} {flag}")

print("\n" + "="*65)
print("TOP PICK: " + results[0]["ticker"])
print("="*65)
r = results[0]
print(f"Price: ${r['price']} | RSI: {r['rsi']} | Regime: {r['regime']}")
print(f"5-day momentum: {r['mom']:+.1f}%")
if r["regime"] == "BULL" and r["rsi"] < 50:
    print("ACTION: BUY - pullback in uptrend")
elif r["regime"] == "BEAR" and r["rsi"] < 35:
    print("ACTION: SPECULATIVE BUY - oversold bounce")
else:
    print("ACTION: WATCH - wait for better entry")
